function render() {
  lang(); const u = U(), a = $('app'); let h = '';
  if (!u) h = st.trk ? trkScreen() : st.rg ? regScreen() : st.screen == 'roles' ? roles() : home();
  else { if (!NAV[u.role].includes(st.tab)) st.tab = NAV[u.role][0]; h = shell(u); }
  a.innerHTML = `<div class="demo">${L('Mode démonstration actif : les données sont simulées et ne sont pas envoyées à un serveur.', 'Demo mode active: data is simulated and is not sent to any server.')}</div>` + h + (st.m ? `<div class="modal" onclick="if(event.target==this)A('close')"><div>${st.err ? `<div class="err" style="margin-top:34px">${esc(st.err)}</div>` : ''}${st.m}</div></div>` : '');
  st.msg = ''; st.err = '';
}
const note = () => (st.err ? `<div class="err">${esc(st.err)}</div>` : '') + (st.msg ? `<div class="okm">${esc(st.msg)}</div>` : '');
